    /** 制药台配药模式：无效输入不开工；配伍失败消耗后产药渣；合法组合产动态注射液。 */
    function tryCompoundAtStation(inputItems) {
        if (guardPlayerActionBlocked(ACTION_TYPES.CRAFT)) {
            return { ok: false, reason: 'action_disabled', action_type: ACTION_TYPES.CRAFT };
        }
        var stationCtx = StationContext.getCurrentPharmacyStationContext();
        if (!stationCtx) return { ok: false, reason: 'not_on_pharmacy_station' };
        if (StationContext.isPharmacyUiBlockedByRepairForContext(stationCtx)) {
            return { ok: false, reason: 'pharmacy_station_repair_locked' };
        }
        if (!Array.isArray(inputItems) || !inputItems.length) return { ok: false, reason: 'empty_inputs' };
        if (PharmacyStation.getActiveCraft()) return { ok: false, reason: 'craft_in_progress' };
        if (!window.PharmacyCompounding || typeof window.PharmacyCompounding.validate !== 'function') {
            return { ok: false, reason: 'compounding_unavailable' };
        }

        var selected = StationCraftCore.normalizePharmacyInputs(inputItems);
        var check = window.PharmacyCompounding.validate(selected);
        if (!check.ok) return check;
        var resolvedPreview = window.PharmacyCompounding.resolve(selected);
        if (!resolvedPreview.ok) return resolvedPreview;
        if (!Array.isArray(resolvedPreview.buff_ids) || !resolvedPreview.buff_ids.length) {
            return { ok: false, reason: 'no_effective_component' };
        }

        var i;
        for (i = 0; i < selected.length; i++) {
            var sid = selected[i].item_id;
            if (InventoryHelpers.getInventoryCountByItemId(sid) < selected[i].count) {
                return { ok: false, reason: 'missing_input_items', item_id: sid };
            }
        }
        if (IE && typeof IE.canAcceptItem === 'function' && !IE.canAcceptItem()) {
            return { ok: false, reason: 'inventory_full' };
        }

        var consumedRes = StationCraftCore.consumeInventoryItemsByList(selected);
        if (!consumedRes.ok) {
            StationCraftCore.putItemsBack(consumedRes.consumed || []);
            return { ok: false, reason: 'consume_inputs_failed' };
        }

        var compoundFailed = resolvedPreview.precipitated === true || (resolvedPreview.conflicts || []).length > 0;
        if (compoundFailed) {
            var residue = { item_id: PharmacyStation.getFailureItemId(), count: 1 };
            var residuePlaced = IE.putItemIntoDefaultContainer(residue);
            if (!residuePlaced || !residuePlaced.placed) {
                var failState = E.getState();
                if (typeof IE.addItemToGround === 'function') IE.addItemToGround(failState.mapId, failState.x, failState.y, residue);
            }
            showMsg(ui('pharmacy.msg.done_fail', { item: residue.item_id }), 'warn');
            if (typeof updateBackpackPanel === 'function') updateBackpackPanel();
            if (window.SceneRenderer) window.SceneRenderer.render();
            return { ok: false, reason: 'incompatible_compound', consumed: true, failure_item_id: residue.item_id, resolved: resolvedPreview };
        }

        var built = window.PharmacyCompounding.buildInstance(selected);
        if (!built.ok) {
            StationCraftCore.putItemsBack(consumedRes.consumed || []);
            return built;
        }
        if (typeof PharmacyStation.inheritSpoilageOnOutput === 'function') {
            PharmacyStation.inheritSpoilageOnOutput(built.instance, consumedRes.consumed || []);
        }
        var placed = IE.putItemIntoDefaultContainer(built.instance);
        if (!placed || !placed.placed) {
            var st0 = E.getState();
            if (typeof IE.addItemToGround === 'function') IE.addItemToGround(st0.mapId, st0.x, st0.y, built.instance);
        }
        if (typeof PharmacyStation.addPharmacySuccessProficiency === 'function') PharmacyStation.addPharmacySuccessProficiency(1);
        var res = built.resolved || {};
        showMsg(ui('pharmacy.compound.ok', {
            used: String(res.concentration_used != null ? res.concentration_used : 0),
            capacity: String(res.capacity != null ? res.capacity : 0),
            tox: String(res.net_toxicity != null ? res.net_toxicity : 0)
        }), 'success');
        if (typeof updateBackpackPanel === 'function') updateBackpackPanel();
        if (typeof updateStatusPanel === 'function') SceneHud.refresh('status');
        if (window.SceneRenderer) window.SceneRenderer.render();
        return { ok: true, instance: built.instance, resolved: res };
    }

    function resolveNpcHardOccupancyAfterWorldTick() {
        if (!E || typeof E.getState !== 'function' || typeof E.getMap !== 'function' || typeof E.setState !== 'function') return false;
        if (!window.NPCSystem || typeof window.NPCSystem.isNpcPresentNow !== 'function') return false;
        var st = E.getState();
        var map = E.getMap();
        if (!st || !map || !Array.isArray(map.npcs) || !map.npcs.length) return false;

        var px = st.x | 0;
        var py = st.y | 0;
        var i;
        for (i = 0; i < map.npcs.length; i++) {
            var n = map.npcs[i];
            if (!n) continue;
            var nx = n.x | 0;
            var ny = n.y | 0;
            if (nx !== px || ny !== py) continue;
            var npcId = n.npc_id != null ? String(n.npc_id) : '';
            if (!npcId) continue;
            if (!window.NPCSystem.isNpcPresentNow(npcId)) continue;
            var target = StationContext.findAdjacentStandableCellAround(nx, ny);
            if (!target) {
                showMsg(ui('scene.msg.npc_occupy_conflict'), 'warn');
                return false;
            }
            E.setState(st.mapId, target.x, target.y);
            if (window.SceneCtx && typeof window.SceneCtx.pushDirtyCell === 'function') {
                window.SceneCtx.pushDirtyCell(nx, ny);
                window.SceneCtx.pushDirtyCell(target.x, target.y);
            }
            showMsg(ui('scene.msg.npc_pushed_away'), 'info');
            return true;
        }
        return false;
    }

    /** 主世界 tick 唯一权威：GameTime.totalTicks（存档 time.totalTicks）；Survival.tickCount 仅作未加载 GameTime 时的回退。 */
    function getWorldTotalTicks() {
        if (window.GameTime && typeof window.GameTime.getState === 'function') {
            var ts = window.GameTime.getState();
            if (ts && typeof ts.totalTicks === 'number' && isFinite(ts.totalTicks)) {
                return Math.max(0, Math.floor(ts.totalTicks));
            }
        }
        if (window.Survival && typeof window.Survival.getState === 'function') {
            var ss = window.Survival.getState();
            if (ss && ss.tickCount != null) return Math.max(0, Math.floor(Number(ss.tickCount) || 0));
        }
        return 0;
    }

    /** agriculture_map.state.tick 仅为世界时间的镜像，禁止独立递增。 */
    function patchSurvivalTickForWorldSystemsOnce() {
        if (!window.Survival || typeof window.Survival.advanceTick !== 'function') return;
        if (window.Survival.__worldSystemsTickPatched) return;
        var oldAdvance = window.Survival.advanceTick;
        window.Survival.advanceTick = function () {
            var ret = oldAdvance.apply(this, arguments);
            try { resolveNpcHardOccupancyAfterWorldTick(); } catch (e2) { /* ignore */ }
            try { CookingStation.tickCookingTempStationsAfterWorldTick(); } catch (e1) { /* ignore */ }
            try { CookingStation.tickCraftAfterWorldTick(); } catch (e0) { /* ignore */ }
            try { tickPharmacyTempStationsAfterWorldTick(); } catch (eP1) { /* ignore */ }
            try { PharmacyStation.tickCraftAfterWorldTick(); } catch (eP0) { /* ignore */ }
            try {
                if (window.CompostSystem && typeof window.CompostSystem.onWorldTick === 'function') {
                    window.CompostSystem.onWorldTick();
                }
            } catch (e3) { /* ignore */ }
            try {
                if (window.CompostPanel && typeof window.CompostPanel.refreshIfOpen === 'function') window.CompostPanel.refreshIfOpen();
            } catch (e4) { /* ignore */ }
            try { tickHideoutWarehouseAfterWorldTick(); } catch (eHwTick) { /* ignore */ }
            try { tickAgricultureAfterWorldTick(); } catch (eAg) { /* ignore */ }
            try { tickLivestockAfterWorldTick(); } catch (eLs) { /* ignore */ }
            try { CombatWorld.tickEnemiesAfterWorldTick(); } catch (eEn) { /* ignore */ }
            if (CombatWorld.flushDisplacements) CombatWorld.flushDisplacements();
            try { CombatWorld.tickPlayerStunDecay(); } catch (eStunD) { /* ignore */ }
            // 制药：成瘾衰减/阶段压制刷新 + 毒性代谢 + 致死倒计时（47 §4/§9.2，k242/k240）
            try {
                if (window.PharmacyEffects && typeof window.PharmacyEffects.onWorldTick === 'function') {
                    window.PharmacyEffects.onWorldTick();
                }
            } catch (ePharmTick) { /* ignore */ }
            // 09「损毁恢复」：部位损毁自然自愈（宽限后按部位速率回落，休息加速）
            try {
                if (window.CharacterAttributes && typeof window.CharacterAttributes.onWorldTickDestroyRecover === 'function') {
                    window.CharacterAttributes.onWorldTickDestroyRecover();
                }
            } catch (ePartRecover) { /* ignore */ }
            return ret;
        };
        window.Survival.__worldSystemsTickPatched = true;
        window.Survival.__cookingCraftPatched = true;
        window.Survival.__pharmacyCraftPatched = true;
    }

    function computeMoveStaminaCost() {
        var base = 0.25;
        try {
            if (window.CharacterAttributes && typeof window.CharacterAttributes.getCfg === 'function') {
                var b = Number(window.CharacterAttributes.getCfg('move_stamina_base', 0.25));
                if (isFinite(b) && b > 0) base = b;
            }
        } catch (eB) { /* ignore */ }
        var shoeMod = 0;
        if (window.InventoryEquipment && typeof window.InventoryEquipment.getShoeSharedMods === 'function') {
            try { shoeMod = Number(window.InventoryEquipment.getShoeSharedMods().moveCostMod) || 0; } catch (eS) { shoeMod = 0; }
        }
        var cost = base * (1 + shoeMod);
        try {
            var IEw = window.InventoryEquipment;
            var CAw = window.CharacterAttributes;
            if (IEw && typeof IEw.getCurrentCarryWeight === 'function' && CAw && typeof CAw.getCarryCapacity === 'function') {
                var W = Number(IEw.getCurrentCarryWeight()) || 0;
                var Wmax = Number(CAw.getCarryCapacity()) || 1;
                if (W > Wmax && Wmax > 0) {
                    var k = 20;
                    try {
                        var kk = Number(window.CharacterAttributes.getCfg('move_stamina_overload_k', 20));
                        if (isFinite(kk) && kk >= 0) k = kk;
                    } catch (eK) { /* ignore */ }
                    cost = cost * (1 + k * ((W - Wmax) / Wmax));
                }
            }
        } catch (eO) { /* ignore */ }
        return Math.max(0.01, Math.round(cost * 100) / 100);
    }

