                    var rmBtn = document.createElement('button');
                    rmBtn.type = 'button';
                    rmBtn.className = 'btn-module-remove';
                    rmBtn.textContent = ui('inv.module.remove');
                    rmBtn.onclick = (function (os, op) {
                        return function () {
                            var res = IE.uninstallModule(os, op);
